    ...(guide.link && guide.link.href.startsWith('steam://') ? [{ label: 'Ссылка Steam', value: guide.link.href }] : []),
    ...guide.copy.filter((c) => c.label === 'Хост' || c.label === 'Порт'),
  ];
  const qrOptions = [
