  'IL', 'AE', 'SA', 'QA', 'EG', 'ZA', 'NG', 'MA', 'IN', 'PK', 'BD', 'CN', 'JP', 'KR', 'TW', 'HK', 'SG', 'MY', 'TH', 'VN', 'ID', 'PH',
