  cat > "$APP_DIR/core-frontend/src/pages/ServerForm.tsx" << '__COREGSM_EOF__'
import { useRef, useState, type FormEvent } from 'react';
import { api, getToken, type ServerInput, type TestResult } from '../api';
import { GAMES } from '../games';
import GamePicker from '../components/GamePicker';
import { ErrorLine, Field, Modal } from '../ui';
import { COUNTRIES } from '../countries';
import { nextPort, shownFields, useGameProfiles } from '../gameProfiles';
import { t } from '../i18n';

export const emptyServer: ServerInput = { name: '', game: 'minecraft', host: '', port: 25565, queryPort: null, displayAddress: '', country: '' };

/** Add / edit a server. The first screen asks only what is needed; the rest is under "Дополнительно". */
export default function ServerForm({ initial, id, coverUrl, onCoverChanged, onClose, onSaved }: { initial: ServerInput; id?: number; coverUrl?: string | null; onCoverChanged?: () => void; onClose: () => void; onSaved: () => void }) {
  const [f, setF] = useState(initial);
  const [cover, setCover] = useState<string | null>(coverUrl ?? null);
  const [coverBusy, setCoverBusy] = useState(false);

  const uploadCover = async (file: File) => {
    if (!id) return;
    setCoverBusy(true);
    setError('');
    try {
      const r = await fetch(`/api/servers/${id}/cover`, { method: 'PUT', headers: { 'Content-Type': file.type, Authorization: `Bearer ${getToken() ?? ''}` }, body: file });
      const j = (await r.json().catch(() => null)) as { coverUrl?: string; error?: string } | null;
      if (!r.ok) throw new Error(j?.error ?? 'Не удалось загрузить картинку (PNG, JPG или WebP до 5 МБ)');
      setCover(j?.coverUrl ?? null);
      onCoverChanged?.();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setCoverBusy(false);
    }
  };
  const removeCover = async () => {
    if (!id) return;
    setCoverBusy(true);
    try {
      await api(`/servers/${id}/cover`, 'DELETE');
      setCover(null);
      onCoverChanged?.();
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setCoverBusy(false);
    }
  };
  const [custom, setCustom] = useState(!GAMES.some((g) => g.id === initial.game));
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [testing, setTesting] = useState(false);
  const [test, setTest] = useState<TestResult | null>(null);

  // "advanced" is open when it already holds something (editing)
  const advancedUsed = !!(initial.name || initial.queryPort || initial.displayAddress || initial.country || coverUrl);

  const profiles = useGameProfiles();
  // true once the user typed a port themselves: a game change must not overwrite it
  const portTouched = useRef(false);

  const pickGame = (v: string) => {
    setTest(null);
    if (v === '__custom') { setCustom(true); return; }
    setCustom(false);
    const g = GAMES.find((x) => x.id === v);
    const nextDefault = profiles?.[v]?.defaultPort ?? g?.port;
    setF((p) => ({
      ...p,
      game: v,
      port: nextPort({
        current: p.port,
        touched: portTouched.current,
        hasHost: !!p.host,
        prevDefault: profiles?.[p.game]?.defaultPort ?? GAMES.find((x) => x.id === p.game)?.port,
        nextDefault,
      }),
    }));
  };

  const change = (patch: Partial<ServerInput>) => {
    setTest(null);
    setF((p) => ({ ...p, ...patch }));
  };

  const gameProfile = custom ? undefined : profiles?.[f.game];
  const fieldList = shownFields(gameProfile?.fields);

  const canTest = f.host.trim().length > 0 && f.game.length > 0 && f.port > 0;

  const runTest = async () => {
    setTesting(true);
    setError('');
    setTest(null);
    try {
      setTest(await api<TestResult>('/servers/test', 'POST', { game: f.game, host: f.host, port: f.port, queryPort: f.queryPort }));
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setTesting(false);
    }
  };

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError('');
    try {
      await api(id ? `/servers/${id}` : '/servers', id ? 'PUT' : 'POST', f);
      onSaved();
    } catch (err) {
      setError((err as Error).message);
      setBusy(false);
    }
  };

  return (
    <Modal title={id ? 'Изменить сервер' : 'Новый сервер'} onClose={onClose}>
      <form onSubmit={submit} className="space-y-3.5">
        <div>
          <span className="label">Игра</span>
          <GamePicker id="srv-game" value={f.game} custom={custom} onPick={pickGame} autoFocus />
        </div>
        {custom && (
          <Field label="GameDig ID">
            <input id="srv-gameid" className="input" value={f.game} onChange={(e) => change({ game: e.target.value.trim() })} placeholder="например, arma3" required pattern="[A-Za-z0-9_]+" />
          </Field>
        )}
        <div className="grid grid-cols-3 gap-3">
          <div className="col-span-2">
            <Field label="Адрес для опроса (IP или домен)">
              <input id="srv-host" className="input" value={f.host} onChange={(e) => change({ host: e.target.value.trim() })} required placeholder="192.168.1.10" />
            </Field>
          </div>
          <Field label="Порт">
            <input id="srv-port" className="input" type="number" min={1} max={65535} value={f.port} onChange={(e) => { portTouched.current = true; change({ port: Number(e.target.value) }); }} required />
          </Field>
        </div>
        {gameProfile?.queryPortHint && <p className="-mt-2 text-sm font-semibold text-mute">{t('sf.queryHint', { hint: gameProfile.queryPortHint })}</p>}
        {fieldList.length > 0 && <p className="-mt-2 text-sm font-semibold text-mute">{t('sf.fields', { list: fieldList.map((k) => t(`sf.field.${k}` as const)).join(' / ') })}</p>}

        <div className="space-y-2">
          <button type="button" className="btn btn-soft" onClick={runTest} disabled={!canTest || testing}>
            {testing ? 'Опрашиваю…' : 'Проверить сервер'}
          </button>
          {test && test.online && (
            <div className="rounded-2xl bg-okbg px-4 py-3 text-sm font-bold text-ok" role="status">
              ✔ Сервер ответил{test.name ? `: «${test.name}»` : ''}
              <div className="mt-0.5 font-semibold">
                Игроков {test.players}/{test.maxPlayers}
                {test.map ? ` · карта ${test.map}` : ''}
                {test.ping != null ? ` · пинг ${test.ping} мс` : ''}
              </div>
            </div>
          )}
          {test && !test.online && (
            <div className="rounded-2xl bg-badbg px-4 py-3 text-sm font-bold text-bad" role="alert">
              ✖ {test.error ?? 'Сервер не ответил'}
            </div>
          )}
        </div>

        <details className="group rounded-2xl border-2 border-line px-4 py-2.5" open={advancedUsed}>
          <summary className="cursor-pointer select-none font-extrabold text-link">Дополнительно</summary>
          <div className="mt-3 space-y-3.5">
            <Field label="Название">
              <input id="srv-name" className="input" value={f.name} onChange={(e) => change({ name: e.target.value })} maxLength={64} placeholder="возьмётся из ответа сервера" />
            </Field>
            <p className="-mt-2 text-sm font-semibold text-mute">Оставьте пустым: панель использует название, которое сервер сообщает сам. Своё название переопределяет его.</p>
            <Field label="Query-порт (если отличается от порта игры)">
              <input id="srv-qport" className="input" type="number" min={1} max={65535} value={f.queryPort ?? ''} onChange={(e) => change({ queryPort: e.target.value ? Number(e.target.value) : null })} placeholder="не указан" />
            </Field>
            <Field label="Адрес для отображения">
              <input id="srv-display" className="input font-mono" value={f.displayAddress} onChange={(e) => change({ displayAddress: e.target.value.trim() })} maxLength={100} placeholder="play.example.com:25565 или внешний IP" />
            </Field>
            <Field label="Страна (для сообщения в Discord)">
              <select id="srv-country" className="input" value={f.country} onChange={(e) => change({ country: e.target.value })}>
                <option value="">Определить автоматически по адресу</option>
                {COUNTRIES.map(([code, name]) => <option key={code} value={code}>{name}</option>)}
              </select>
            </Field>
            <p className="-mt-2 text-sm font-semibold text-mute">Автоопределение не работает для адресов в локальной сети: выберите страну вручную, и флаг появится в сообщении.</p>
            <p className="-mt-2 text-sm font-semibold text-mute">Опрос идёт по адресу выше, а людям на странице и в карточке Discord показывается этот адрес. Нужен, если сервер в локальной сети, а снаружи доступен по другому IP или домену.</p>
            <div>
              <span className="label">Обложка</span>
              {id ? (
                <div className="flex flex-wrap items-center gap-3">
                  <div className="h-[72px] w-32 shrink-0 overflow-hidden rounded-xl border border-line bg-soft" style={cover ? { backgroundImage: `url(${cover})`, backgroundSize: 'cover', backgroundPosition: 'center' } : undefined} aria-hidden />
                  <label className="btn btn-soft btn-sm cursor-pointer">
                    {coverBusy ? 'Загружаю…' : 'Загрузить картинку'}
                    <input type="file" accept="image/png,image/jpeg,image/webp" className="hidden" disabled={coverBusy} onChange={(e) => { const file = e.target.files?.[0]; if (file) void uploadCover(file); e.target.value = ''; }} />
                  </label>
                  {cover && <button type="button" className="btn btn-soft btn-sm" onClick={() => void removeCover()} disabled={coverBusy}>Убрать</button>}
                  <span className="basis-full text-sm font-semibold text-mute">PNG, JPG или WebP до 5 МБ; обрезается до 16:9. Заменяет цветную обложку карточки и шапку страницы сервера.</span>
                </div>
              ) : (
                <p className="text-sm font-semibold text-mute">Картинку можно загрузить после создания сервера: откройте «Изменить».</p>
              )}
            </div>
          </div>
        </details>

        <ErrorLine text={error} />
        <div className="flex justify-end gap-2 pt-1">
          <button type="button" className="btn btn-soft" onClick={onClose}>Отмена</button>
          <button className="btn" disabled={busy || !canTest}>{busy ? 'Сохраняю…' : 'Сохранить'}</button>
        </div>
      </form>
    </Modal>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages"
  cat > "$APP_DIR/core-frontend/src/pages/Servers.tsx" << '__COREGSM_EOF__'
import { useEffect, useMemo, useState, type CSSProperties, type MouseEvent } from 'react';
import { api, type Server, type StatusInfo } from '../api';
import { useAuth } from '../auth';
import { gameColor, gameGradient, gameLabel } from '../games';
import { coverBackground } from '../cover';
import MaintenanceChip from '../components/MaintenanceChip';
import { AnimatedNumber, Burst, ErrorLine, GameAvatar, LoadError, IconServers, PageHead, Spark, StatusPill, ago, isLag, plural, useDepth, usePoll } from '../ui';
import { t, useI18n } from '../i18n';
import { CapacityBar, CountReact, ListSkeleton, NoFavsState, NoMatchState, NoServersState, StatusFlash, TilesSkeleton, reactionOf, useServerReactions, type Reactions } from '../components/servers/serverUi';
import { ServersList, ServersTv, readView, saveView, type SelectProps, type ServersView } from '../components/servers/ServerViews';
import { PulseStrip } from '../components/servers/PulseStrip';
import { WhatsNew, useWhatsNewOpen } from '../components/servers/WhatsNew';
import { BulkBar } from '../components/servers/BulkBar';
import { pickHero, type HeroReason, type OverviewData } from '../components/servers/overviewLogic';
import NotFound from '../components/NotFound';
import ServerDetail, { SERVER_TABS } from './ServerDetail';

export default function ServersPage({ sub }: { sub: string }) {
  // "12/players" -> server 12, tab "players"
  const [idPart = '', tabPart = ''] = sub.split('/');
  const id = Number(idPart);
  const tab = (SERVER_TABS as readonly string[]).includes(tabPart) ? tabPart : '';
  if (idPart && /^\d+$/.test(idPart) && Number.isInteger(id) && id > 0 && (!tabPart || tab)) return <ServerDetail id={id} tab={tab} />;
  // "#/servers/abc" or an unknown tab: not a server page
  if (sub) return <NotFound kind="server" />;
  return <ServerList />;
}

/** a greeting for the signed-in user: «Доброе утро, Иван» */
function greeting(name: string): string {
  const h = new Date().getHours();
  const hello = h >= 5 && h < 12 ? 'Доброе утро' : h >= 12 && h < 18 ? 'Добрый день' : h >= 18 && h < 23 ? 'Добрый вечер' : 'Доброй ночи';
  return `${hello}, ${name.trim() || name}`;
}

function FavButton({ on, name, onClick, className = '' }: { on: boolean; name: string; onClick: () => void; className?: string }) {
  // the star pops (scale, tilt and a few sparks) only after the user's own click, not when the list loads
  const [pops, setPops] = useState(0);
  return (
    <button
      onClick={(e) => { e.stopPropagation(); if (!on) setPops((n) => n + 1); onClick(); }}
      className={`grid h-9 w-9 place-items-center rounded-full text-xl leading-none transition hover:scale-110 max-sm:h-11 max-sm:w-11 ${className}`}
      title={on ? 'Убрать из избранного' : 'В избранное'}
      aria-label={`В избранное: ${name}`}
      aria-pressed={on}
    >
      <span className="star-wrap">
        <span key={on ? pops : 'off'} className={on && pops > 0 ? 'star-pop' : ''} aria-hidden>{on ? '★' : '☆'}</span>
        {on && pops > 0 && <Burst key={pops} count={6} radius={15} />}
      </span>
    </button>
  );
}

type Filter = 'all' | 'online' | 'offline' | 'fav';
const FILTER_KEY = 'coregsm_server_filter';

/** staggered entrance: the tile number goes to the --i custom property */
const stagger = (i: number): CSSProperties => ({ ['--i' as string]: i });

/** a small "live" indicator: pulsing dot and how fresh the data is */
function LiveBadge({ at }: { at: number }) {
  const [, tick] = useState(0);
  useEffect(() => {
    const t = window.setInterval(() => tick((n) => n + 1), 5000);
    return () => window.clearInterval(t);
  }, []);
  if (!at) return null;
  return (
    <span className="inline-flex items-center gap-2 rounded-full bg-soft px-3 py-1 text-xs font-extrabold text-mute" title="Страница обновляется сама">
      <span className="live-dot" aria-hidden />
      обновлено {ago(at)}
    </span>
  );
}

function ServerList() {
  const { me, isAdmin } = useAuth();
  const [favs, setFavs] = useState<number[]>([]);
  useEffect(() => {
    if (me) api<number[]>('/favorites').then(setFavs).catch(() => undefined);
    else setFavs([]);
  }, [me]);
  const toggleFav = async (id: number) => {
    const on = favs.includes(id);
    setFavs(on ? favs.filter((x) => x !== id) : [...favs, id]);
    await api(`/favorites/${id}`, on ? 'DELETE' : 'PUT').catch(() => undefined);
  };
  const [servers, setServers] = useState<Server[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState('');
  const [uptime, setUptime] = useState<Map<number, number>>(new Map());
  const [updatedAt, setUpdatedAt] = useState(0);
  const [filter, setFilterState] = useState<Filter>(() => {
    try {
      // deep link: #/servers?filter=online
      const q = window.location.hash.match(/[?&]filter=(\w+)/)?.[1];
      const v = q ?? localStorage.getItem(FILTER_KEY);
      return v === 'online' || v === 'offline' || v === 'fav' ? v : 'all';
    } catch {
      return 'all';
    }
  });
  const setFilter = (f: Filter) => {
    setFilterState(f);
    try {
      localStorage.setItem(FILTER_KEY, f);
    } catch {
      /* not remembered */
    }
  };

  const [view, setViewState] = useState<ServersView>(readView);
  const setView = (v: ServersView) => { setViewState(v); saveView(v); };

  const load = () =>
    api<Server[]>('/servers')
      .then((s) => { setServers(s); setError(''); setUpdatedAt(Date.now()); })
      .catch((e) => setError(e.message))
      .finally(() => setLoaded(true));
  // the TV mode refreshes twice as often
  usePoll(load, view === 'tv' ? 5_000 : 10_000);
  const rx = useServerReactions(servers, loaded);
  // 30-day availability comes from the public status endpoint; the tile is simply hidden when it has no data
  usePoll(
    () => api<StatusInfo>('/status')
      .then((r) => setUptime(new Map(r.servers.filter((x) => x.uptime30 != null).map((x) => [x.id, x.uptime30 as number]))))
      .catch(() => undefined),
    5 * 60_000,
  );

  // total players over the last 24 h (the pulse strip) and planned maintenance (the news block)
  const [overview, setOverview] = useState<OverviewData | null>(null);
  const [overviewAt, setOverviewAt] = useState(0);
  usePoll(
    () => api<OverviewData>('/overview?hours=24').then((o) => { setOverview(o); setOverviewAt(Date.now()); }).catch(() => undefined),
    60_000,
  );
  const [wnOpen, toggleWn] = useWhatsNewOpen();

  const sorted = useMemo(
    () => [...servers].sort((a, b) => Number(favs.includes(b.id)) - Number(favs.includes(a.id)) || Number(b.online) - Number(a.online)),
    [servers, favs],
  );
  const online = servers.filter((s) => s.online);
  const upVals = servers.map((s) => uptime.get(s.id)).filter((v): v is number => v != null);
  const upAvg = upVals.length ? upVals.reduce((a, b) => a + b, 0) / upVals.length : null;

  // the hero by meaning: a server that needs attention, else the busiest favourite, else the busiest server
  const picked = useMemo(() => pickHero(sorted, me ? favs : []), [sorted, favs, me]);
  const hero = picked?.server ?? null;
  const heroReason: HeroReason = picked?.reason ?? null;
  const rest = sorted.filter((s) => s.id !== hero?.id);
  const offlineCount = servers.filter((s) => !s.online).length;
  const favCount = servers.filter((s) => favs.includes(s.id)).length;
  // a filter other than "all" turns the bento into a plain grid of the matching servers
  const effFilter: Filter = filter === 'fav' && !me ? 'all' : filter;
  const filtered = effFilter === 'all' ? [] : sorted.filter((s) => (effFilter === 'online' ? s.online : effFilter === 'offline' ? !s.online : favs.includes(s.id)));

  const effView: ServersView = servers.length === 0 ? 'tiles' : view;
  const visible = effFilter === 'all' ? sorted : filtered;
  const resetFilter = () => setFilter('all');

  // ---- bulk selection (administrators; not in the TV mode) ----
  const [selecting, setSelecting] = useState(false);
  const [sel, setSel] = useState<number[]>([]);
  const canSelect = isAdmin && effView !== 'tv' && servers.length > 0;
  const selOn = canSelect && selecting;
  const selectedServers = servers.filter((s) => sel.includes(s.id));
  const exitSelect = () => { setSelecting(false); setSel([]); };
  useEffect(() => {
    if (!selOn) return;
    const onKey = (e: KeyboardEvent) => {
      // a dialog on top closes itself first
      if (e.key === 'Escape' && !document.querySelector('[role="dialog"]')) exitSelect();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [selOn]);
  const select: SelectProps | undefined = selOn
    ? { on: true, has: (id) => sel.includes(id), toggle: (id) => setSel((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id])) }
    : undefined;

  const open = (s: Server) => { window.location.hash = `#/servers/${s.id}`; };

  const tileProps = (s: Server, idx: number) => ({
    rx,
    s,
    idx,
    fav: me ? favs.includes(s.id) : null,
    onFav: () => void toggleFav(s.id),
    onOpen: () => open(s),
    select,
  });

  return (
    <div className="space-y-5">
      <PageHead
        title="Серверы"
        subtitle={me ? `${greeting(me.username)}. Серверы в реальном времени` : 'Состояние ваших игровых серверов в реальном времени'}
        icon={<IconServers />}
      >
        <LiveBadge at={updatedAt} />
        {isAdmin && <a className="btn btn-soft" href="#/admin/servers" data-magnetic>Управление серверами</a>}
      </PageHead>

      {loaded && servers.length > 0 && effView !== 'tv' && (
        <PulseStrip servers={servers} overview={overview} uptime={upAvg} now={overviewAt || updatedAt} />
      )}

      {servers.length > 0 && (
        <div className="srv-bar">
          {servers.length > 1 ? (
            <nav className="seg flex w-fit max-w-full overflow-x-auto" aria-label="Фильтр серверов">
              {([
                ['all', `Все · ${servers.length}`],
                ['online', `Онлайн · ${online.length}`],
                ['offline', `Недоступные · ${offlineCount}`],
                ...(me ? [['fav', `Избранные · ${favCount}`]] : []),
              ] as [Filter, string][]).map(([id, label]) => (
                <button key={id} type="button" className="seg-item whitespace-nowrap" aria-pressed={effFilter === id} onClick={() => setFilter(id)}>{label}</button>
              ))}
            </nav>
          ) : <span />}
          <div className="flex flex-wrap items-center gap-2.5">
            {canSelect && (
              <button type="button" className={`btn btn-soft ${selOn ? 'srv-sel-on' : ''}`} aria-pressed={selOn} onClick={() => (selOn ? exitSelect() : setSelecting(true))} title="Выбрать несколько серверов для массовых действий">
                {selOn ? 'Отменить выбор' : 'Выбрать'}
              </button>
            )}
            <div className="seg" role="group" aria-label="Вид списка">
              {([['tiles', 'Плитки'], ['list', 'Список'], ['tv', 'ТВ']] as [ServersView, string][]).map(([id, label]) => (
                <button key={id} type="button" className="seg-item" aria-pressed={effView === id} onClick={() => setView(id)} title={id === 'tv' ? 'Экран для большого телевизора' : undefined}>{label}</button>
              ))}
            </div>
          </div>
        </div>
      )}
      {error && servers.length === 0 ? <LoadError error={error} onRetry={() => void load()} /> : <ErrorLine text={error} />}

      {!loaded && (effView === 'list' ? <ListSkeleton /> : <TilesSkeleton />)}

      {loaded && !error && servers.length === 0 && <NoServersState isAdmin={isAdmin} />}

      {servers.length > 0 && effView === 'tv' && visible.length > 0 && (
        <ServersTv servers={visible} uptime={uptime} rx={rx} updatedAt={updatedAt} onExit={() => setView('tiles')} />
      )}

      {servers.length > 0 && effView !== 'tv' && (
        <div className="srv-split" data-open={wnOpen}>
          <div className="min-w-0 space-y-5">
            {visible.length === 0 && (
              effFilter === 'fav' && favCount === 0
                ? <NoFavsState onReset={resetFilter} />
                : <NoMatchState what={effFilter === 'offline' ? 'offline' : 'online'} onReset={resetFilter} />
            )}

            {visible.length > 0 && effView === 'list' && (
              <ServersList
                servers={visible}
                uptime={uptime}
                rx={rx}
                favOf={(id) => (me ? favs.includes(id) : null)}
                onOpen={open}
                select={select}
                renderFav={(sv, on) => <FavButton on={on} name={sv.name} onClick={() => void toggleFav(sv.id)} className={on ? 'text-warn' : 'text-mute'} />}
              />
            )}

            {effView === 'tiles' && effFilter !== 'all' && visible.length > 0 && (
              <div className="fade-in grid grid-cols-2 gap-3.5 lg:grid-cols-12">
                {filtered.map((s, i) => <SmallTile key={s.id} {...tileProps(s, i)} />)}
              </div>
            )}

            {effView === 'tiles' && effFilter === 'all' && (
              <div className="fade-in grid grid-cols-2 gap-3.5 lg:grid-cols-12">
                {hero && <HeroTile key={hero.id} {...tileProps(hero, 0)} reason={heroReason} uptime={uptime.get(hero.id)} />}
                {rest.map((s, i) => <SmallTile key={s.id} {...tileProps(s, i + 1)} />)}
              </div>
            )}
          </div>
          <WhatsNew open={wnOpen} onToggle={toggleWn} overview={overview} />
        </div>
      )}

      {selOn && (
        <BulkBar
          selected={selectedServers}
          visible={visible}
          favs={favs}
          onSelectAll={() => setSel(visible.map((s) => s.id))}
          onClear={() => setSel([])}
          onExit={exitSelect}
          onReload={() => void load()}
          onFavs={setFavs}
        />
      )}
    </div>
  );
}

/** the checkbox of the selection mode in a corner of a card */
function CardCheck({ s, select, className = '' }: { s: Server; select: SelectProps; className?: string }) {
  return (
    <input
      type="checkbox"
      className={`srv-check srv-check-card ${className}`}
      checked={select.has(s.id)}
      onChange={() => select.toggle(s.id)}
      onClick={(e) => e.stopPropagation()}
      aria-label={`Выбрать: ${s.name}`}
    />
  );
}

/** in the selection mode a link toggles the card instead of leaving the page */
const linkClick = (s: Server, select?: SelectProps) => (e: MouseEvent<HTMLElement>) => {
  e.stopPropagation();
  if (select?.on) {
    e.preventDefault();
    select.toggle(s.id);
  }
};

function HeroTile({ s, idx, uptime, fav, onFav, onOpen, rx, reason, select }: { rx: Reactions; s: Server; idx: number; uptime?: number; fav: boolean | null; onFav: () => void; onOpen: () => void; reason: HeroReason; select?: SelectProps }) {
  useI18n();
  const [c1, c2] = gameGradient(s.game);
  const lag = isLag(s);
  const depth = useDepth<HTMLElement>();
  const r = reactionOf(rx, s.id);
  return (
    <article
      className={`depth tile-in tile-hover relative col-span-2 flex cursor-pointer flex-col gap-3 overflow-hidden rounded-[26px] p-5 text-white shadow-soft lg:col-span-6 lg:row-span-2 lg:p-6 ${reason === 'attention' ? 'hero-attn' : ''}`}
      style={{
        ...stagger(idx),
        background: coverBackground(s.coverUrl, `linear-gradient(140deg, ${c1}, ${c2})`, { strong: true, game: s.game }),
        boxShadow: `${select?.has(s.id) ? '0 0 0 3px rgb(var(--brand)), ' : reason === 'attention' ? '0 0 0 3px rgb(var(--bad) / .85), ' : ''}0 1px 2px rgba(20,24,40,.06), 0 18px 40px -12px ${c1}88`,
      }}
      onClick={select?.on ? () => select.toggle(s.id) : onOpen}
      {...depth}
    >
      <span aria-hidden className="depth-l1 pointer-events-none absolute -right-16 -top-16 h-64 w-64 rounded-full bg-white/15" />
      <span aria-hidden className="depth-l2 pointer-events-none absolute -bottom-24 -left-10 h-52 w-52 rounded-full bg-black/10" />
      {select?.on && <CardCheck s={s} select={select} className="left-2 top-2" />}

      <div className="relative flex items-start gap-3">
        <GameAvatar game={s.game} size={48} glass vtId={s.id} />
        <div className="min-w-0 flex-1">
          <h2 className="line-clamp-2 break-words text-lg font-extrabold leading-tight sm:text-xl" title={s.name}>
            <a href={`#/servers/${s.id}`} onClick={linkClick(s, select)} className="hover:underline">{s.name}</a>
          </h2>
          <div className="mt-0.5 flex flex-wrap items-center gap-x-2 text-[13px] font-bold text-white/90">
            <span>{gameLabel(s.game)}</span>
            <span aria-hidden>·</span>
            <code className="truncate font-mono text-xs font-semibold" title={s.address}>{s.address}</code>
          </div>
          {s.maintenance && <MaintenanceChip m={s.maintenance} glass className="mt-1.5" />}
          {reason && <span className={`hero-reason ${reason === 'attention' ? 'attn' : ''}`}>{t(`srv.hero.${reason}` as const)}</span>}
        </div>
        <div className="flex shrink-0 items-center gap-1">
          <StatusFlash r={r}><StatusPill glass online={s.online} known={s.hasStatus} lag={lag} maintenance={!!s.maintenance} /></StatusFlash>
          {fav != null && <FavButton on={fav} name={s.name} onClick={onFav} className={fav ? 'text-white' : 'text-white/80'} />}
        </div>
      </div>

      {s.online ? (
        <>
          <div className="relative flex flex-wrap items-baseline gap-x-2.5 gap-y-1 pt-1">
            <CountReact r={r} onDark><AnimatedNumber value={s.players} className="text-[64px] font-extrabold leading-none tracking-[-0.045em] sm:text-[78px]" /></CountReact>
            <span className="text-lg font-bold text-white/90">/ {s.maxPlayers} {plural(s.maxPlayers, ['игрок', 'игрока', 'игроков'])}</span>
            {s.ping != null && <span className="ml-auto font-bold text-white/90">пинг {s.ping} мс</span>}
          </div>
          <CapacityBar className="relative" players={s.players} max={s.maxPlayers} color="#fff" onDark />
          <div className="relative mt-auto pt-2">
            <Spark serverId={s.id} color="#ffffff" variant="hero" />
          </div>
        </>
      ) : (
        s.hasStatus && (
          <div className="relative mt-4 rounded-2xl bg-white/20 px-4 py-3" title={s.error ?? undefined}>
            <p className="line-clamp-3 text-base font-extrabold leading-snug">{s.error ?? 'Сервер не отвечает'}</p>
            <p className="mt-1 text-sm font-semibold text-white/85">Последний ответ: {ago(s.updatedAt)}</p>
          </div>
        )
      )}

      <div className="relative mt-auto flex flex-wrap items-center justify-between gap-x-4 gap-y-1 text-[13px] font-bold text-white/90">
        <span>за 24 часа</span>
        {uptime != null && <span>аптайм {(Math.round(uptime * 10) / 10).toLocaleString('ru-RU')}%</span>}
        <span className="truncate">{s.online && s.map ? `карта ${s.map}` : `обновлено ${ago(s.updatedAt)}`}</span>
      </div>
    </article>
  );
}

function SmallTile({ s, idx, fav, onFav, onOpen, rx, select }: { rx: Reactions; s: Server; idx: number; fav: boolean | null; onFav: () => void; onOpen: () => void; select?: SelectProps }) {
  const [c1, c2] = gameGradient(s.game);
  const lag = isLag(s);
  const r = reactionOf(rx, s.id);
  return (
    <article
      className={`tile tile-in tile-hover relative col-span-2 flex cursor-pointer flex-col gap-1.5 p-2.5 pb-3.5 sm:col-span-1 lg:col-span-3 ${select?.has(s.id) ? 'srv-selected' : ''}`}
      style={stagger(idx)}
      onClick={select?.on ? () => select.toggle(s.id) : onOpen}
    >
      {select?.on && <CardCheck s={s} select={select} className="left-1 top-1" />}
      <div className={`flex h-[88px] items-start justify-between rounded-[18px] p-2.5 ${s.online ? '' : 'offline-cover'}`} style={{ background: coverBackground(s.coverUrl, `linear-gradient(135deg, ${c1}, ${c2})`, { small: true, game: s.game }), boxShadow: `inset 0 -3px 0 ${gameColor(s.game)}` }}>
        <GameAvatar game={s.game} size={40} glass vtId={s.id} />
        <div className="flex items-center gap-0.5">
          <StatusFlash r={r}><StatusPill glass online={s.online} known={s.hasStatus} lag={lag} maintenance={!!s.maintenance} /></StatusFlash>
          {fav != null && <FavButton on={fav} name={s.name} onClick={onFav} className={`-mr-1 -mt-0.5 ${fav ? 'text-white' : 'text-white/85'}`} />}
        </div>
      </div>

      <div className="px-1.5">
        <h3 className="line-clamp-2 break-words text-[14.5px] font-extrabold leading-tight" title={s.name}>
          <a href={`#/servers/${s.id}`} onClick={linkClick(s, select)} className="hover:text-link">{s.name}</a>
        </h3>
        <div className="mt-0.5 truncate text-[13px] font-bold text-mute">{gameLabel(s.game)}</div>
        {s.maintenance && <MaintenanceChip m={s.maintenance} className="mt-1" />}
      </div>

      {s.online ? (
        <>
          <div className="flex items-baseline gap-1.5 px-1.5">
            <CountReact r={r}><AnimatedNumber value={s.players} className="text-[30px] font-extrabold leading-none tracking-[-0.03em]" /></CountReact>
            <span className="font-bold text-mute">/ {s.maxPlayers}</span>
            <span className="ml-auto text-[13px] font-bold text-mute">{s.ping != null ? `${s.ping} мс` : ''}</span>
          </div>
          <CapacityBar className="px-1.5" players={s.players} max={s.maxPlayers} color={gameColor(s.game)} />
          <div className="px-1.5"><Spark serverId={s.id} color={gameColor(s.game)} /></div>
        </>
      ) : (
        s.hasStatus ? (
          <div className="mx-1.5 flex items-center gap-2 rounded-xl bg-badbg px-3 py-2" title={s.error ?? undefined}>
            <span className="h-2 w-2 shrink-0 rounded-full bg-bad" aria-hidden />
            <p className="truncate text-[13px] font-bold leading-snug text-bad">Не отвечает · {ago(s.updatedAt)}</p>
          </div>
        ) : (
          <div className="mx-1.5 rounded-xl bg-soft px-3 py-2.5 text-[13px] font-bold text-mute">Ожидаем первый ответ</div>
        )
      )}

      <div className="mt-auto flex items-center justify-between gap-2 px-1.5 pt-1 text-xs font-bold text-mute">
        <span className="truncate font-mono" title={s.address}>{s.address}</span>
        <span className="shrink-0">{s.online && s.map ? s.map : ago(s.updatedAt)}</span>
      </div>
    </article>
  );
}
